CREATE TABLE public.matturo_profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', photo_path text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.matturo_profiles TO authenticated; GRANT ALL ON public.matturo_profiles TO service_role;
ALTER TABLE public.matturo_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_self_read ON public.matturo_profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_self_update ON public.matturo_profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.matturo_user_roles (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','courier')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.matturo_user_roles TO authenticated; GRANT ALL ON public.matturo_user_roles TO service_role;
ALTER TABLE public.matturo_user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_self ON public.matturo_user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.matturo_has_role(wanted text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.matturo_user_roles WHERE user_id=auth.uid() AND role=wanted) $$;
REVOKE ALL ON FUNCTION public.matturo_has_role(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.matturo_has_role(text) TO authenticated;
CREATE POLICY profiles_admin_read ON public.matturo_profiles FOR SELECT TO authenticated USING(public.matturo_has_role('admin'));
CREATE POLICY roles_admin_read ON public.matturo_user_roles FOR SELECT TO authenticated USING(public.matturo_has_role('admin'));
CREATE TABLE public.matturo_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL, courier_id uuid REFERENCES public.matturo_profiles(id), destination text NOT NULL, destination_lat double precision NOT NULL CHECK(destination_lat BETWEEN -90 AND 90), destination_lng double precision NOT NULL CHECK(destination_lng BETWEEN -180 AND 180), status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','active','delivered','cancelled')), confirmed_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.matturo_deliveries TO authenticated; GRANT ALL ON public.matturo_deliveries TO service_role;
ALTER TABLE public.matturo_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY deliveries_read ON public.matturo_deliveries FOR SELECT TO authenticated USING(courier_id=auth.uid() OR public.matturo_has_role('admin'));
CREATE POLICY deliveries_admin_insert ON public.matturo_deliveries FOR INSERT TO authenticated WITH CHECK(public.matturo_has_role('admin') AND status='confirmed');
CREATE POLICY deliveries_admin_update ON public.matturo_deliveries FOR UPDATE TO authenticated USING(public.matturo_has_role('admin')) WITH CHECK(public.matturo_has_role('admin'));
CREATE TABLE public.matturo_delivery_positions (delivery_id uuid PRIMARY KEY REFERENCES public.matturo_deliveries(id) ON DELETE CASCADE, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy double precision NOT NULL CHECK(accuracy>=0), recorded_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.matturo_delivery_positions TO authenticated; GRANT ALL ON public.matturo_delivery_positions TO service_role;
ALTER TABLE public.matturo_delivery_positions ENABLE ROW LEVEL SECURITY;
CREATE POLICY positions_read ON public.matturo_delivery_positions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.matturo_deliveries d WHERE d.id=delivery_id AND d.status='active' AND (d.courier_id=auth.uid() OR public.matturo_has_role('admin'))));
CREATE TABLE public.matturo_delivery_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES public.matturo_deliveries(id) ON DELETE CASCADE, status text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.matturo_delivery_events TO authenticated; GRANT ALL ON public.matturo_delivery_events TO service_role;
ALTER TABLE public.matturo_delivery_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.matturo_delivery_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.matturo_deliveries d WHERE d.id=delivery_id AND (d.courier_id=auth.uid() OR public.matturo_has_role('admin'))));
CREATE TABLE public.matturo_tracking_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES public.matturo_deliveries(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.matturo_tracking_links TO service_role;
ALTER TABLE public.matturo_tracking_links ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.matturo_touch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profile_touch BEFORE UPDATE ON public.matturo_profiles FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE TRIGGER roles_touch BEFORE UPDATE ON public.matturo_user_roles FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE TRIGGER delivery_touch BEFORE UPDATE ON public.matturo_deliveries FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE TRIGGER position_touch BEFORE UPDATE ON public.matturo_delivery_positions FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE TRIGGER events_touch BEFORE UPDATE ON public.matturo_delivery_events FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE TRIGGER links_touch BEFORE UPDATE ON public.matturo_tracking_links FOR EACH ROW EXECUTE FUNCTION public.matturo_touch();
CREATE FUNCTION public.matturo_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.matturo_profiles(id,name) VALUES(NEW.id,''); RETURN NEW; END $$;
CREATE TRIGGER matturo_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.matturo_create_profile();
CREATE FUNCTION public.matturo_delivery_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.courier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.matturo_user_roles WHERE user_id=NEW.courier_id AND role='courier') THEN RAISE EXCEPTION 'Entregador não autorizado'; END IF; IF TG_OP='UPDATE' THEN IF NEW.status<>OLD.status AND NOT ((OLD.status='confirmed' AND NEW.status IN ('active','cancelled')) OR (OLD.status='active' AND NEW.status IN ('delivered','cancelled'))) THEN RAISE EXCEPTION 'Transição inválida'; END IF; IF OLD.status='active' AND NEW.courier_id IS DISTINCT FROM OLD.courier_id THEN RAISE EXCEPTION 'Não reatribuir entrega ativa'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER delivery_guard BEFORE INSERT OR UPDATE ON public.matturo_deliveries FOR EACH ROW EXECUTE FUNCTION public.matturo_delivery_guard();
CREATE FUNCTION public.matturo_delivery_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.matturo_delivery_events(delivery_id,status,actor_id) VALUES(NEW.id,NEW.status,auth.uid()); END IF; IF NEW.status IN ('delivered','cancelled') THEN DELETE FROM public.matturo_delivery_positions WHERE delivery_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER delivery_audit AFTER INSERT OR UPDATE ON public.matturo_deliveries FOR EACH ROW EXECUTE FUNCTION public.matturo_delivery_audit();
CREATE FUNCTION public.matturo_set_delivery_state(delivery uuid, next_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.matturo_deliveries; BEGIN SELECT * INTO d FROM public.matturo_deliveries WHERE id=delivery FOR UPDATE; IF NOT FOUND OR d.courier_id IS DISTINCT FROM auth.uid() OR NOT public.matturo_has_role('courier') THEN RAISE EXCEPTION 'Sem acesso'; END IF; IF NOT ((d.status='confirmed' AND next_state='active') OR (d.status='active' AND next_state='delivered')) THEN RAISE EXCEPTION 'Transição inválida'; END IF; UPDATE public.matturo_deliveries SET status=next_state,started_at=CASE WHEN next_state='active' THEN now() ELSE started_at END,completed_at=CASE WHEN next_state='delivered' THEN now() ELSE completed_at END WHERE id=delivery; END $$;
REVOKE ALL ON FUNCTION public.matturo_set_delivery_state(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.matturo_set_delivery_state(uuid,text) TO authenticated;
CREATE FUNCTION public.matturo_record_position(delivery uuid, lat double precision, lng double precision, precision_m double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.matturo_deliveries; BEGIN SELECT * INTO d FROM public.matturo_deliveries WHERE id=delivery FOR UPDATE; IF NOT FOUND OR d.courier_id IS DISTINCT FROM auth.uid() OR d.status<>'active' OR NOT public.matturo_has_role('courier') THEN RAISE EXCEPTION 'Rastreamento não autorizado'; END IF; INSERT INTO public.matturo_delivery_positions(delivery_id,latitude,longitude,accuracy) VALUES(delivery,lat,lng,precision_m) ON CONFLICT(delivery_id) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,accuracy=EXCLUDED.accuracy,recorded_at=now(); END $$;
REVOKE ALL ON FUNCTION public.matturo_record_position(uuid,double precision,double precision,double precision) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.matturo_record_position(uuid,double precision,double precision,double precision) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.matturo_deliveries, public.matturo_delivery_positions;
